        Method skipMethod = LookaheadInputStream.class.getDeclaredMethod("skip", long.class);
        skipMethod.setAccessible(true);
        long result = (long) skipMethod.invoke(lookaheadInputStream, 1);
        assertEquals(0, result);
        assertEquals(0, getPrivateField(lookaheadInputStream, "position"));
    }

    private Object getPrivateField(Object obj, String fieldName) throws NoSuchFieldException, IllegalAccessException {
        Field field = obj.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(obj);
    }
}
